SELECT
  min(latitude) AS min_latitude,
  min(longitude) AS min_longitude,
  max(latitude) AS max_latitude,
  max(longitude) AS max_longitude,
  cast(sum(population) as integer) AS population
FROM yemen_2020
WHERE
  type='total_population'
  AND ST_Within(
    ST_Point(longitude, latitude),
    ST_Polygon('POLYGON ((46.0585799 15.4926955,46.0477036 16.5276636,44.1552364 17.3807451,43.9812164 17.3288395,43.6331765 17.4015032,43.480909 17.5260023,43.263384 17.474138,43.0784878 17.5260023,42.6869428 17.474138,42.6264334 16.8663186,42.8222059 15.8854399,42.7025671 15.7179962,43.311637 13.7194365,43.1919983 13.2858373,43.6052957 12.7135747,43.8445732 13.1164159,44.2034894 13.1164159,44.3883856 13.3281742,44.4971481 13.571467,44.3992619 13.8145106,44.6602919 13.9939891,45.1823518 14.015095,45.3998768 13.8778718,45.628278 13.8778718,45.9219367 13.9834354,46.0850804 14.3103732,46.2808529 14.4999906,46.0089467 14.6999664,45.7696692 14.5421058,45.8458029 14.4157361,45.6391542 14.6052637,45.4868867 14.7735956,45.541268 15.0468566,45.6391542 15.1938525,45.671783 15.2043483,45.671783 15.2043483,45.8458029 15.298787,45.9654417 15.4036689,46.0585799 15.4926955))')
  );
